import unittest
from candidate import poly, find_zero

class TestPolynomialOperations(unittest.TestCase):
    def test_poly_constant(self):
        self.assertAlmostEqual(poly([5], 0), 5)

    def test_poly_linear(self):
        self.assertAlmostEqual(poly([2, 3], 2), 8)

    def test_poly_quadratic(self):
        self.assertAlmostEqual(poly([1, 2, 3], 2), 17)

    def test_poly_cubic(self):
        self.assertAlmostEqual(poly([1, 2, 3, 4], 2), 39)

    def test_poly_with_negative_coefficients(self):
        self.assertAlmostEqual(poly([-1, 2, -3], 2), -11)

    def test_poly_with_fractional_coefficients(self):
        self.assertAlmostEqual(poly([1.5, 2.5, 3.5], 2), 20.5)

    def test_find_zero_linear(self):
        self.assertAlmostEqual(find_zero([1, 2]), -0.5)

    def test_find_zero_quadratic(self):
        self.assertAlmostEqual(find_zero([1, -3, 2]), 1.0)

    def test_find_zero_Cubic(self):
        self.assertAlmostEqual(find_zero([-6, 11, -6, 1]), 1.0)

    def test_find_zero_with_negative_coefficients(self):
        self.assertAlmostEqual(find_zero([-1, -2, 3]), 1.0)

    def test_find_zero_with_fractional_coefficients(self):
        self.assertAlmostEqual(find_zero([1.5, -2.5, 3.5]), 1.0)

    def test_find_zero_empty_input(self):
        with self.assertRaises(TypeError):
            find_zero([])

    def test_find_zero_none_input(self):
        with self.assertRaises(TypeError):
            find_zero(None)

    def test_find_zero_odd_coefficients(self):
        with self.assertRaises(AssertionError):
            find_zero([1, 2, 3, 4, 5])

    def test_find_zero_non_list_input(self):
        with self.assertRaises(TypeError):
            find_zero("coefficients")

if __name__ == '__main__':
    unittest.main()
